'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=v=>String(v??'').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,''), formatted=v=>esc(plain(v)).replace(/\n/g,'<br>'), motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
let S=null,D=null,current='prologue',bookmark=null,selectedHits=[],lineNumber=0;
try{bookmark=JSON.parse(localStorage.getItem('cr-story-bookmark-v1')||'null');}catch{}
const post=()=>$('#storyPostgame').checked;
const order=()=>['prologue','act1','act2',...($('#journeyOrder').value==='vard'?['fury','act3']:['act3','fury']),'fury_reunion','act4','act5','finale','epilogue','restore1','restore2','restore3','restore4','mari_reunion','restore5','restore6','restore7','restore8','restored','kaoru_cafe','seam'];
const available=()=>order().map(id=>S.stories.find(s=>s.id===id)).filter(s=>s&&(post()||!s.postgame));
const backgrounds={rain:'アクアミストの雨',teal:'潮の国',glass:'灰色の街・記録院',forest:'茨の森',canyon:'赤い丘・黄金の渓谷',stars:'星空とクリスタリア',cave_sky:'虹の国',restoration:'クリスタリアの復興'};
const speakerColors={...S?.speakers,'クロム':'#b8cce4','ノアール':'#bcd5e7','ノア':'#bcd5e7'};
function voice(who,text,storyId){const c=S.speakers[who],color=c&&/^#[a-f0-9]{6}$/i.test(c)?c:'#bad3df';return `<div class="dialogue" style="--speaker:${color}" data-story="${storyId}" data-line="${lineNumber++}"><b>${esc(who)}</b><p>${formatted(text)}</p></div>`;}
function line(text,id){const m=text.match(/^([^「」\s]{1,24})「([\s\S]*)」$/);if(m)return voice(m[1],'「'+m[2]+'」',id);if(text.startsWith('>'))return `<p class="story-center" data-story="${id}" data-line="${lineNumber++}">${formatted(text.slice(1).trim())}</p>`;return `<p class="narrative" data-story="${id}" data-line="${lineNumber++}">${formatted(text)}</p>`;}
function journeyChat(key){if(key==='forest_before')return $('#journeyOrder').value==='vard'?S.chats.fury.forest_before:'';if(key==='forest_after')return $('#journeyOrder').value==='vard'?S.chats.fury.forest_after:S.chats.fury.forest_after_ivy_first;if(key==='forest_meeting')return $('#journeyOrder').value==='ivy'?S.chats.fury.forest_meeting:'';return S.chats.fury[key]||'';}
function chatLines(text,id){return text.split('\n').filter(l=>l.trim()).map(l=>line(l,id)).join('');}
function battle(id,storyId){const c=D.stages.find(s=>s.id===id);if(!c)return'';const p=D.guardians.find(p=>p.id===c.guardian);let text=`<section class="battle-story"><p class="eyebrow">この場面の戦闘</p><h4>${esc(c.title)}</h4><p>${esc(c.description)}${c.beacons?` ${c.beacons}つの灯を点け、敵を全滅させる。`:''}</p><a class="text-link" href="index.html#stages" data-guide-stage="${id}">この戦場のS攻略を見る →</a>`;
if(p){text+=`<details open><summary>戦闘中に戻ってくる、3段階の声</summary>${p.phases.map((v,i)=>`<div class="voice-phase"><h5>${['Ⅰ','Ⅱ','Ⅲ'][i]} / ${v.name} · ${v.skill}</h5>${v.lines.map(([who,t])=>voice(who,'「'+t+'」',storyId)).join('')}</div>`).join('')}<div class="voice-phase"><h5>穢れをほどいた後</h5>${voice(p.name,'「'+p.freed+'」',storyId)}</div></details>`;}if(id==='chrome')text+=`<details open><summary>心剣を2回当てた後の、戦闘中の物語</summary>${S.phase0.split('\n').map(l=>l.trim()).filter(l=>l&&!l.startsWith('@')).map(l=>line(l,storyId)).join('')}</details>`;return text+'</section>';}
function choice(key,id){const c=S.choices[key];if(!c)return'';return `<section class="choice-story"><p class="eyebrow">この場面の選択肢</p><p>${formatted(c.prompt)}</p>${c.options.map(o=>`<details ${o.ok?'open':''}><summary class="${o.ok?'choice-ok':''}">${esc(o.t)}${o.ok?' / 物語が進む選択':''}</summary>${o.lines.filter(l=>!l.startsWith('@')).map(l=>line(l,id)).join('')}</details>`).join('')}</section>`;}
function renderBody(story){const id=story.id;let html='',lastBg='';lineNumber=0;for(const raw of story.script.split('\n')){const l=raw.trim();if(!l||l.startsWith('#'))continue;if(!l.startsWith('@')){html+=line(l,id);continue;}const space=l.indexOf(' '),cmd=space<0?l.slice(1):l.slice(1,space),arg=space<0?'':l.slice(space+1).trim();if(cmd==='bg'){const bg=arg.split(' ')[0];if(backgrounds[bg]&&bg!==lastBg){html+=`<div class="story-scene">${esc(backgrounds[bg])}</div>`;lastBg=bg;}}if(cmd==='board')html+=battle(arg,id);if(cmd==='choice')html+=choice(arg,id);if(cmd==='cg'&&arg==='lila-wave')html+='<figure class="story-cg"><img src="media/lila-wave.png" alt="港の波の中、子どもたちを先に渡し綱を握るリラ" loading="lazy"><figcaption>波の夜 · リラが握り続けた綱</figcaption></figure>';if(cmd==='toast')html+=`<p class="story-event">${formatted(arg)}</p>`;if(cmd==='vardbond')html+='<p class="story-event">ヴァルドが旅の仲間に加わる。</p>';if(cmd==='maribond')html+='<p class="story-event">マリーが自ら精霊としての旅を選び、仲間に加わる。</p>';if(cmd==='rejoin')html+='<p class="story-event">人間のクロムとアリア、浄化の剣となったノアール。クリスタリア復興の旅が始まる。</p>';if(cmd==='end')html+='<p class="story-event">クロム撃破後のエピローグが完了。本編クリア、ここから復興の物語へ。</p>';if(cmd==='restored')html+='<p class="story-event">クリスタリア復興の本編が完了。明日の修理へ、旅は続く。</p>';if(cmd==='furynews'){html+=chatLines(S.chats.fury.mari_news_before,id);if(post())html+=`<details class="variant-story"><summary>マリー救出後にこの丘を訪れた場合の会話</summary>${chatLines(S.chats.fury.mari_news,id)}</details>`;}if(cmd==='furychat'){let t=arg==='ending'?S.chats.fury.ending_before:journeyChat(arg);if(t){html+=`<p class="small-note">${arg==='ending'?'丘を離れる前に':`${arg.startsWith('forest_')?'選んだ加入順の出会い':arg==='gran'||arg==='ivy'?'森と丘をつないだ仲間の会話':`${{spinel:'スピネル',king:'パレット王'}[arg]}加入後に丘を訪れたときの会話`}`}</p>`+chatLines(t,id);if(arg==='ending'&&post())html+=`<details class="variant-story"><summary>クロム撃破後の、復興へ続く会話</summary>${chatLines(S.chats.fury.ending,id)}</details>`;}}if(cmd==='marichat'){if(arg==='vard')html+='<p class="small-note">紅角の旅で結んだ、マリーとの再会。</p>';html+=chatLines(S.chats.mari[arg]||'',id);}if(cmd==='recall')html+=`<details class="variant-story" open><summary>選んだ修理順によって戻る言葉</summary><h5>苗床を先に守ったとき</h5>${line('先に守った苗床には、新しい芽が出ていた。翌日つないだ橋を、種を運ぶ人が渡っていった。',id)}<h5>橋を先に直したとき</h5>${line('先に直した橋を、離れていた家族が渡っていった。翌日守った苗床へ、その人たちが水を運んだ。',id)}</details>`;}return html;}
function renderIndex(){const list=available();$('#chapterIndex').innerHTML=['本編','交流・後日談','復興編','最終章'].map((group,i)=>{const chapters=list.filter(s=>i===0?['prologue','act1','act2','act3','fury','act4','act5','finale','epilogue'].includes(s.id):i===1?['fury_reunion','mari_reunion','kaoru_cafe'].includes(s.id):i===2?s.id.startsWith('restore'):s.id==='seam');return chapters.length?`<p class="index-group">${group}</p>`+chapters.map(s=>`<button data-chapter="${s.id}" aria-pressed="${s.id===current}"><small>${esc(s.act)}</small>${esc(s.title)}</button>`).join(''):'';}).join('');}
function renderReader(){const list=available();if(!list.some(s=>s.id===current))current='prologue';renderIndex();const shown=$('#readerMode').value==='continuous'?list:[S.stories.find(s=>s.id===current)];$('#storyReader').innerHTML=shown.map(s=>`<section class="story-chapter" id="read-${s.id}" data-chapter-body="${s.id}"><header><p class="eyebrow">${esc(s.act)}</p><h3>${esc(s.title)}</h3><p>${s.id==='seam'?'復興編と馨のカフェのあと、テラ・コッタで。':s.id==='kaoru_cafe'?'復興を読み終えたあとの、戦わない後日談。':s.postgame?'クロム撃破後の復興と、その続き。':s.id.startsWith('fury')?'第三幕解放後の、紅角の丘。':'アリアとノアールの旅。'}現在のゲーム本文・全会話を収録。</p></header>${renderBody(s)}<p class="story-event">${esc(s.act)}「${esc(s.title)}」の記録はここまで。</p></section>`).join('');$('#storyReader').dataset.font=$('#readerFont').value;const pos=list.findIndex(s=>s.id===current);$('#prevChapter').disabled=pos<=0;$('#nextChapter').disabled=pos>=list.length-1;$('#readingStatus').textContent=`${S.stories.find(s=>s.id===current).act}を表示 / ${post()?'全20編':'本編と紅角の丘の10編'}。全章モードでは目次から各章へ移動できます。`;}
function navigate(id,lineIndex=null){const story=S.stories.find(s=>s.id===id);if(!story)return;if(story.postgame)$('#storyPostgame').checked=true;current=id;history.replaceState(null,'','#'+id);renderReader();const target=lineIndex===null?$('#read-'+id):document.querySelector(`[data-story="${id}"][data-line="${lineIndex}"]`);if(target){target.closest('details')?.setAttribute('open','');target.scrollIntoView({behavior:motion(),block:'start'});if(lineIndex!==null){target.classList.add('story-highlight');setTimeout(()=>target.classList.remove('story-highlight'),5000);}}}
const characters=[{id:'aria',name:'アリア・クリスタ',role:'心剣を持つ主人公',chapter:'prologue',text:'表情よりも手が語る十六歳の少女。心の色を感じるが、相手の答えを先に決めないことを、リラから学んだ。'},{id:'lila',name:'リラ',role:'アリアを育てた母',chapter:'prologue',text:'薬草と茶、ほどきやすい結び目。相手を急がせず、人の心そのものを切らないようアリアへ伝えた。'},{id:'renoir',name:'ノアール（ノア）',role:'透明の王家の眷属・旅の相棒',chapter:'act1',text:'アリアと同じ夜に生まれ、ひとり国に残された眷属。捨てられた色を吸って黒くなり、待っていた相手を忘れた。理由もわからないままアリアへ寄っていく。本当の役目は、どんな色も失わずに運ぶ方舟。'},{id:'gran',name:'グラン',role:'潮の精霊・帰りを待つ鯨',chapter:'act1',text:'渡り鳥マリーが戻るたびに旅の話を聞いていた。長い悲しみの奥に、あの子と海を守りたい気持ちが残る。'},{id:'kaoru',name:'馨',role:'灰色の街の書記・最終章の相手',chapter:'act2',text:'チクタクの下で乾いた音を抱える。三日間で自分の一行を書き、旅の手帳を書き続ける。けれど彼は、十六年前に向こう側から落ちてきた人だった。最終章で、アリアに最後の頼みをする。'},{id:'ivy',name:'アイビー',role:'蔦と木陰の精霊',chapter:'act3',text:'姉ルミナへの愛情と、比べられた痛みを同時に抱える。マリーとは森の木陰で語り合い、赤い丘へ帰る葉の目印を残した。休める木陰を守り、相手が出ていく道を閉じない。'},{id:'lumina',name:'ルミナ',role:'アイビーの姉・光の精霊',chapter:'act3',text:'鳥籠に閉じ込められた恐怖を伝えながら、自分の花が妹の根に支えられていることも、初めて言葉にする。'},{id:'spinel',name:'スピネル',role:'傷の光で守る精霊',chapter:'act4',text:'傷を見られる恐怖から鉛へ閉じこもった。割れたところの光を隠さず、仲間の守りやヴァルドの角を支える。'},{id:'vard',name:'ヴァルド',role:'赤い丘の紅い竜・憤怒の精霊',chapter:'fury',text:'盗まれた生命の実のせいで、妻ルベラと生まれるはずだった子を失った。怒りは本人のもので、浄化しても消えず、生きるための火に変わる。角にはルベラの赤い紐。戦闘直後、グランと「潮の友」になる。'},{id:'king',name:'パレット王',role:'七色の調和を守る人間の王',chapter:'act5',text:'世界を黒へ染める命令に侵されていた。解放後、旅の仕組みと光の国クリスタリアのことを語る。国に残って命令を取り消して回るため旅には加わらず、宝具「双彩の王笏」を託す。'},{id:'mari',name:'マリー',role:'世界を知る渡り鳥',chapter:'restore4',text:'各地の人や精霊と交流が深く、土地・歌・道具の知識も豊富。帰れなかった声の続きは、復興本編の第4話へつながる。'},{id:'chrome',name:'クロム',role:'夜空の黒を抱えた男',chapter:'finale',text:'黒を好きな自分を否定された痛みから、どこかで溢れていた闇をノアに吸わせて国へ流し、他人の心へ穢れをまいた。闇を生んだのは彼ではない。それでも、その行いの責任は消えない。'}];
function renderCharacters(){$('#characterCards').innerHTML=characters.map(c=>`<article class="character-card"><img src="media/${c.id}.png" alt="${c.name}" loading="lazy"><p class="character-role">${c.role}</p><h3>${c.name}</h3><p>${c.text}</p><a class="text-link" href="#${c.chapter}" data-character-chapter="${c.chapter}">${c.chapter==='restore4'?'帰還の章を読む（クリア後）':'関わる章を読む'} →</a></article>`).join('');}
function searchable(s){let t=s.script.split('\n').filter(l=>l&&!l.startsWith('@')&&!l.startsWith('#')).join('\n');for(const m of s.script.matchAll(/^@board (\w+)/gm)){const p=D.guardians.find(p=>p.bossId===m[1]);if(p)t+='\n'+p.lines.flat().map(([w,t])=>w+t).join('\n');if(m[1]==='chrome')t+='\n'+S.phase0;}for(const m of s.script.matchAll(/^@(furychat|marichat) (\w+)/gm))t+='\n'+(m[1]==='furychat'?journeyChat(m[2]):S.chats.mari[m[2]]||'');if(s.script.includes('@furynews'))t+='\n'+(post()?S.chats.fury.mari_news:S.chats.fury.mari_news_before);for(const m of s.script.matchAll(/^@choice (\w+)/gm)){const c=S.choices[m[1]];if(c)t+='\n'+c.prompt+'\n'+c.options.map(o=>o.t+'\n'+o.lines.join('\n')).join('\n');}return plain(t);}
function search(){const q=$('#storySearch').value.trim(),box=$('#storySearchResults');box.hidden=!q;if(!q)return;selectedHits=available().flatMap(s=>searchable(s).split('\n').filter(l=>l.includes(q)).map(text=>({id:s.id,title:s.title,act:s.act,text})));box.innerHTML=`<p class="small-note">${selectedHits.length}件${selectedHits.length>40?' / 先頭40件を表示':''} · ${post()?`全${available().length}編から検索`:'復興編の本文は非表示'}</p>`+selectedHits.slice(0,40).map((r,i)=>`<button data-hit="${i}"><small>${r.act} / ${r.title}</small><span>${esc(r.text.slice(0,160))}</span></button>`).join('')+(selectedHits.length?'':'<p>該当する言葉がありません。短い単語で検索してください。</p>');}
function onHit(i){const h=selectedHits[i];if(!h)return;navigate(h.id);const q=$('#storySearch').value.trim();const target=[...document.querySelectorAll(`[data-story="${h.id}"]`)].find(el=>el.textContent.includes(q)&&h.text.includes(el.textContent.replace(/\s+/g,'')))||[...document.querySelectorAll(`[data-story="${h.id}"]`)].find(el=>el.textContent.includes(q));if(target){let p=target.parentElement;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}target.classList.add('story-highlight');target.scrollIntoView({behavior:motion(),block:'center'});}else $('#readingStatus').textContent='選択肢・時期違いの会話に含まれる言葉です。この章の各会話を開いて確認できます。';}
function saveBookmark(){const visible=[...document.querySelectorAll('[data-story][data-line]')].filter(el=>el.getBoundingClientRect().top>=95&&el.getBoundingClientRect().top<innerHeight);const target=visible[0]||document.querySelector(`[data-story="${current}"]`);bookmark={chapter:target?.dataset.story||current,line:Number(target?.dataset.line)||0,journeyOrder:$('#journeyOrder').value};try{localStorage.setItem('cr-story-bookmark-v1',JSON.stringify(bookmark));$('#readingStatus').textContent=`「${S.stories.find(s=>s.id===bookmark.chapter).title}」にしおりを挟みました。次回ここへ戻れます。`;}catch{$('#readingStatus').textContent='このブラウザではしおりを保存できません。章のURLを保存してください。';}}
function installStoryMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const life=new AbortController();const tools=[{name:'get_story_chapter',title:'物語の章を読む',description:'表示設定で開いている章の本文・会話・戦闘中の声・選択肢の文章を返す。ゲームの進行は変更しない。',inputSchema:{type:'object',properties:{chapterId:{type:'string'}},required:['chapterId'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='chapterId')||typeof input.chapterId!=='string')throw Error('有効なchapterIdが必要です。');const s=available().find(s=>s.id===input.chapterId);if(!s)throw Error('その章は未表示、または存在しません。');return{id:s.id,title:s.title,act:s.act,text:searchable(s).split('\n').filter(l=>!l.startsWith('@')).join('\n')};}},{name:'search_story_record',title:'物語の本文を検索',description:'画面と同じネタバレ設定で、本文・選択肢・戦闘中の声から言葉を探す。',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:80}},required:['query'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='query')||typeof input.query!=='string'||!input.query.trim()||input.query.length>80)throw Error('1〜80文字の検索語が必要です。');const q=input.query.trim();return{matches:available().flatMap(s=>searchable(s).split('\n').filter(l=>!l.startsWith('@')&&l.includes(q)).map(text=>({chapterId:s.id,title:s.title,text}))).slice(0,40)};}}];for(const t of tools)try{Promise.resolve(ctx.registerTool({...t,annotations:{readOnlyHint:true,untrustedContentHint:false}},{signal:life.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>life.abort(),{once:true});}
function setup(){const hash=location.hash.slice(1);if(S.stories.some(s=>s.id===hash)){current=hash;if(S.stories.find(s=>s.id===hash).postgame)$('#storyPostgame').checked=true;}$('#journeyOrder').onchange=()=>{renderReader();search();};$('#storyPostgame').onchange=()=>{renderReader();search();};$('#readerFont').onchange=()=>{$('#storyReader').dataset.font=$('#readerFont').value;};$('#readerMode').onchange=()=>{renderReader();$('#read-'+current)?.scrollIntoView({behavior:motion()});};$('#storySearch').oninput=search;$('#bookmarkStory').onclick=saveBookmark;$('#resumeStory').onclick=()=>{if(bookmark&&S.stories.some(s=>s.id===bookmark.chapter)&&Number.isInteger(bookmark.line)){if(['ivy','vard'].includes(bookmark.journeyOrder))$('#journeyOrder').value=bookmark.journeyOrder;navigate(bookmark.chapter,bookmark.line);}else $('#readingStatus').textContent='しおりはまだありません。読んでいる位置で「しおりを挟む」を押してください。';};$('#prevChapter').onclick=()=>{const list=available(),i=list.findIndex(s=>s.id===current);if(i>0)navigate(list[i-1].id);};$('#nextChapter').onclick=()=>{const list=available(),i=list.findIndex(s=>s.id===current);if(i<list.length-1)navigate(list[i+1].id);};document.addEventListener('click',e=>{const b=e.target.closest('[data-chapter],[data-character-chapter],[data-hit],[data-guide-stage]');if(!b)return;if(b.dataset.chapter){navigate(b.dataset.chapter);}if(b.dataset.characterChapter){e.preventDefault();navigate(b.dataset.characterChapter);}if(b.dataset.hit!==undefined)onHit(+b.dataset.hit);if(b.dataset.guideStage){e.preventDefault();location.href='index.html?stage='+encodeURIComponent(b.dataset.guideStage)+'#stages';}});addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(S.stories.some(s=>s.id===id))navigate(id);});renderReader();renderCharacters();installStoryMCP();$('#storyLoadStatus').textContent=`全${order().filter(id=>S.stories.some(s=>s.id===id)).length}編の本文、選択肢、17体の戦闘中の声を読み込みました。`;if(hash&&S.stories.some(s=>s.id===hash))setTimeout(()=>$('#read-'+current)?.scrollIntoView({behavior:'auto'}),0);}
const menu=$('.menu-button');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open);};$('#navigation').querySelectorAll('a').forEach(a=>a.onclick=()=>{menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open');});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open');menu.focus();}});
